mapper.sql:
d.is_public = 1
AND EXISTS (
    SELECT 1 FROM destination_categories dc
    JOIN categories c ON c.id = dc.category_id
    WHERE dc.destination_id = d.id AND c.name = #{categoryName}
)
AND EXISTS (
    SELECT 1 FROM destination_images di
    WHERE di.destination_id = d.id AND di.is_main = 1 AND TRIM(di.image_url) <> ''
)

mapper.select:
SELECT d.id AS destination_id, d.region_id AS region_id, dt.name, main_image.image_url AS image_url, COALESCE(main_image.card_position_x, 50) AS card_position_x, COALESCE(main_image.card_position_y, 50) AS card_position_y, cc.region_name AS region_name, pcc.id AS parent_region_id, pcc.region_name AS parent_region_name, d.season, NULL AS category_id, NULL AS category_name FROM destinations d JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' JOIN country_categories cc ON d.region_id = cc.id LEFT JOIN country_categories pcc ON cc.parent_id = pcc.id LEFT JOIN destination_images main_image ON main_image.id = ( SELECT di.id FROM destination_images di WHERE di.destination_id = d.id AND di.is_main = 1 AND TRIM(di.image_url) <> '' ORDER BY di.order_index, di.id LIMIT 1 ) WHERE
AND d.id IN
#{id}
AND 1 = 0
LIMIT #{limit}

SELECT d.id AS destination_id, d.region_id AS region_id, dt.name, ( SELECT di.image_url FROM destination_images di WHERE di.destination_id = d.id AND di.is_main = 1 ORDER BY di.order_index ASC, di.id ASC LIMIT 1 ) AS image_url, cc.region_name AS region_name, pcc.id AS parent_region_id, pcc.region_name AS parent_region_name, d.season, NULL AS category_id, NULL AS category_name FROM destinations d LEFT JOIN ( SELECT dvd.destination_id, SUM(dvd.view_count) AS recent_views FROM destination_view_daily dvd WHERE dvd.view_date BETWEEN #{fromDate} AND #{toDate} GROUP BY dvd.destination_id ) recent ON recent.destination_id = d.id LEFT JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' LEFT JOIN country_categories cc ON d.region_id = cc.id LEFT JOIN country_categories pcc ON cc.parent_id = pcc.id WHERE d.is_public = 1 AND ( d.season = #{season}
OR EXISTS ( SELECT 1 FROM destination_categories dc JOIN categories c ON c.id = dc.category_id WHERE dc.destination_id = d.id AND c.name IN
#{categoryName}
)
) ORDER BY COALESCE(recent.recent_views, 0) DESC, d.id ASC LIMIT #{limit}
